INSERT INTO Definition (word_id, language_id, pos_id, definition, example)
VALUES (11027,3,1,'နှစ်ဆယ့်လေးလုံးမြောက်မွန်ဗျည်း။',NULL)
,(11028,3,4,'ခြောက်သည်။',NULL)
,(11029,3,4,'ခြောက်သည်။ ခြောက်လှန့်သည်။','“ကၠဵုဒမျိုၚ် (သၟိၚ်ဣန်ဗဒှ်လဝ်) ဂှ်တုန် ဘကမၠတဴညးအိုတ်ရ။” (ဇ—၄၆၉။ အစွောံ။) = “သိကြားမင်းဖန်ဆင်းထားသော ခွေးနက်ကြီးသည် လူများကို ခြောက်လှန့်၏။”')
,(11030,3,1,'အနက်။','ဘနက်ဘနက်က္ၜံၚ် = ဒူးဆစ်မြုပ်သောအနက်။')
,(11030,3,1,'အနက်။','‘ဗၞက်’ ရှု။')
,(11031,3,4,'ခြောက်လှန့်သည်။','“ဒေဝတဴဂှ် နရုပ်မဂပ်ဂဝ်ဖေက်ဂၟံက်ဂှ် ဘဗဟေက်တုဲ ဗက်ဗဒဴကၠေံကၠကဵုဇာဒိသိုၚ်ဂှ်ရ။” (ဇ—၂၇၂။ အစွောံ။) = “ထိုနတ်သည် ကြောက်မက်ဖွယ်ကောင်းသော ရုပ်ကိုဖန်ဆင်း၍ ကျားနှင့်ခြင်္သေ့တို့ကို ခြောက်လှန့်၍ မောင်းထုတ်လိုက်၏။”')
,(11032,3,10,'(န) အကြောက်။ ကြောက်ခြင်း။',NULL)
,(11033,3,4,'ပြွတ်သိပ်သည်။ များပြားသည်။','“တၞးဆုလဘိုက်၊ ဘမြိုက်ပ္ကဴသတ်။” (လိက်မေဃကောန်ဒြာဲ) = “သစ်ရွက်များဝေဆာ၍ အသီးအပွင့်များပြွတ်သိပ်နေ၏။”')
,(11034,3,10,'(န) ဘေးရန်။ ဘယာ။',NULL)
,(11035,3,10,'(န) ကြောက်ခြင်းကြောင့်ဖြစ်သော အဂတိတရား။ ဘယာဂတိ။',NULL)
,(11036,3,10,'(န) (စာပေ) ထိတ်လန့်ကြောက်ရွံ့မှုရသ။ ဘယာနကရသ။',NULL)
,(11037,3,4,'‘ဗယာပ်’ ရှု။',NULL)
,(11038,3,10,'(န) ဘဝ။ အဖြစ်။ ဖြစ်ခြင်း။',NULL)
,(11039,3,1,'အခြေအနေ အလုပ်အကိုင်စသည် တူညီသူ။ ဘဝတူ။',NULL)
,(11040,3,11,'(န) သတ္တဝါတို့ဖြစ်ရာ သုံးဆယ့်တစ်ဘုံတွင် အမြင့်ဆုံးသောဗြဟ္မာဘုံ။ဘဝဂ်။',NULL)
,(11041,3,1,'မောင်းထုတ်ခြင်း။ နှင်ထုတ်ခြင်း။','“ၜိုန်ဟွံမွဲကဵုဒုဟ်တၚ် ညးနၚ်ဒုဟ်ဘဝက် ဗက်ကၠေံဟွံကဵုဒၟံၚ်—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ပြစ်ချက်တစ်စုံတစ်ရာ မရှိပါဘဲလျက် သူတစ်ပါးတို့က နှင်ထုတ်ခြင်းအပြစ်ကိုပြု၍ မနေစေရန် နှင်ထုတ်ပစ်၏။”')
,(11041,3,1,'မောင်းထုတ်ခြင်း။ နှင်ထုတ်ခြင်း။','“အဲဝွံ ဒှ်မၞိဟ်ဘဝက် ညးမဗက်ကၠေံ နူကဵုဍုၚ်တုဲရ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ငါသည် တိုင်းပြည်မှ နှင်ထုတ်ခြင်းခံထားရသူဖြစ်ခဲ့ပြီ။”')
,(11042,3,1,'နောက်လိုက်။','‘ဗွက်')
,(11042,3,1,'နောက်လိုက်။','ဗွက်ကြဴ’ ရှု။')
,(11043,3,1,'နောက်လိုက်အခြံအရံ။','‘ဗွက်တၞက်’ ရှု။')
,(11044,3,11,'(န) ဝီထိစိတ်အစဉ်နှစ်ခု၏ အကြားဖြစ်သောစိတ်အစဉ်။ ဘဝၚ်။ ဘဝၚ်စိတ်။ (ပါဠိ—ဘဝၚ်္ဂ)',NULL)
,(11045,3,4,'ဝီထိစိတ်အစဉ်ပြတ်၍ ဘဝၚ်စိတ်အစဉ်သို့ရောက်သည်။ ဘဝၚ်ကျသည်။',NULL)
,(11046,3,4,'ဘဝၚ်မြင့်သည်။ မာနကြီးသည်။ စိတ်ကြီးဝၚ်သည်။',NULL)
,(11047,3,1,'ကျောင်း။','ဘာဗ္တောန်လိက် = စာသၚ်ကျောင်း။')
,(11047,3,1,'ကျောင်း။','ဘာလကျာ် = ဘုန်းကြီးကျောင်း။')
,(11048,3,1,'ကျောင်းငယ်။ (ပါဠိ—ကုဋိ)',NULL)
,(11049,3,10,'(န) အဖော်။ ခရီးသွားဖော်။','“တဳလပိုဲဗၚ်ယသဂြော ပဘာဂကဵုသဒၚ်ဂြဳ ညးၜါ—ကၠောံအာ။” (အကြီုရာဇာဓိရာဇ်) = “အရှင်စကြိုသူမြတ်သည် ကျောင်းထိုင်လက်ထောက်ကိုအဖော်ပြု၍ လှေဖြင့်ကူးသွား၏။”')
,(11049,3,10,'(န) အဖော်။ ခရီးသွားဖော်။','“တဳလပိုန်သၚ်ဗၚ်ယသဂြော သီုသဒၚ်ဂြဳမဒှ်ဘာဂ သီုၜါဇကုလုပ်ကၠုၚ်စိုပ်။” (အကြီုရာဇာဓိရာဇ်)')
,(11050,3,10,'(န) အိုး၊ ခွက်၊ ပန်းကန်စသည်။','“ဘာဇနမရပ်စပ်ပ္ဍဲသ္ၚိသၟိၚ်ဂှ် အောန်အာ—။” (ဇ—၄ဝ၉။ အစွောံ။) = “မင်းအိမ်­သုံးသော အိုးခွက်ပန်းကန်နည်းသွား၏။”')
,(11050,3,10,'(န) အိုး၊ ခွက်၊ ပန်းကန်စသည်။','ဘာဇနဣသိ =ရသေ့၏သပိတ်။')
,(11051,3,10,'(န) ဘာဝနာ။ ကမ္မဋ္ဌာန်းပွားများခြင်း။','ပၟဝ်ဘာဝနာ = ဘာဝနာပွားသည်။')
,(11052,3,10,'(န) ၁။ ဘာသာစကား။','ဘာသာမန် = မွန်ဘာသာ။')
,(11052,3,10,'(န) ၁။ ဘာသာစကား။','၂။ ကိုးကွယ်ရာဘာသာ။ဘာသာတရား။')
,(11052,3,10,'(န) ၁။ ဘာသာစကား။','ဗုဒ္ဓဘာသာ = ဗုဒ္ဓဘာသာ။')
,(11052,3,10,'(န) ၁။ ဘာသာစကား။','ဘာသာခရေတ်၊ ဘာသာခရေတ်ယာန် = ခရစ်ယန်ဘာသာ။')
,(11052,3,10,'(န) ၁။ ဘာသာစကား။','ဘာသာဟိန္ဒူ = ဟိန္ဒူဘာသာ။')
,(11052,3,10,'(န) ၁။ ဘာသာစကား။','(ကြိဝိ) ဖာသာ။ သီးခြား။')
,(11052,3,10,'(န) ၁။ ဘာသာစကား။','“ကၠေၚ်ကဵုဍာ်ထကဵုပ္ကောံပမွဲ သဘဴကောံနွံဟာ။ ဍာ်ဂှ်နွံဘာသာဍာ် ကၠေၚ်ဂှ်မံၚ်ဘာသာကၠေၚ်ဂှ်ရ။” (အကြီုရာဇာဓိရာဇ်) = “ဆီနှင့်ရေကို ရောမွှေသဖြင့် တစ်သားတည်းဖြစ်ရိုးရှိသလား။ ရေကရေဖာသာဆီကဆီဖာသာ သီးခြားဖြစ်နေလိမ့်မည်။”')
,(11053,3,10,'(န) ဘာသာစကားကို စိစစ်လေ့လာသည့်ပညာ။ ဘာသာဗေဒ။',NULL)
,(11054,3,10,'(န) မိမိဘာသာစကားမှ တစ်ပါးသောဘာသာစကား။ ဘာသန္တရ။','‘ကတ်လ္ၚတ်ဘာသန္တရ’ = ‘မိမိဘာသာစကားမဟုတ်သော အခြားဘာသာစကားကို လေ့လာသင်ကြားသည်။’')
,(11055,3,10,'(န) အဘိသိက်သွန်းခြင်း။','ပ္တန်ဘိသေခ = ဘိသိက်သွန်းခြင်းဖြင့် ဘုရင်၊မိဖုရားစသူတို့ကို တင်မြှောက်သည်။')
,(11056,3,11,'(န) အဘိသိက်။ အဘိသိက်သွန်းခြင်း။','“သၟိၚ်ဇၞော်မိၚ်ပၠန်၊ ကော်ကောန်ဆတ္တဝ်။ ကဵုအာဒုၚ်ပၠန်၊ ဘိသိက်ကၠောန်လဝ်။ ကဵုဗလိုပ်ရ၊ ခဏဂှ်ဓဝ်။” (လိက်ကောန်သၟိၚ်ပိ။မာံခစုန်အံက်။) = “မင်းကြီးကြားသည်ရှိသော် သားတော်ကိုခေါ်စေ၍ သွားကြိုစေ၍ အဘိသိက်ရေကို စီစဉ်ထားပြီးလျှင် ထိုခဏ­ သွန်းလောင်းစေ၏။”')
,(11057,3,11,'(န) ကြီးဆဲပွားဆဲသစ်ပင်အပေါင်း။ မြက်သစ်ပင်အပေါင်း။ (ပါဠိ—ဘူတဂါမ)',NULL)
,(11058,3,11,'(န) ပထဝီ၊ အာပေါ၊ တေဇော၊ ဝါယောဟူသော ရုပ်ကြီးလေးပါ။ ဘူတရုပ်။မဟာဘုတ်။',NULL)
,(11059,3,10,'(န) မြေအပြင်ကို စောင့်ရှောက်တော်မူသောမင်း။ ရေမြေ့ရှင်မင်း။',NULL)
,(11060,3,10,'(န) မြေလွှာမြေထုနှင့် ပတ်သက်သောပညာရပ်။ ဘူမိဗေဒ။',NULL)
,(11061,3,1,'ကမ္ဘာမြေကြီး။ ကမ္ဘာလောကနှင့် ပတ်သက်သောအရာ။ လောကီရေးရာ။ လောကီလူသား။','“ဂလာန်ဘူဝတ်၊ သတ်ပ္ဍဲလိုက်ဗာ။ ဖျေံညးပ္တိုန်အဲ၊ နဲဝွံဂၠိုၚ်ဝါ။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “လောကလူသားများသည် လောကီရေးရာစကားကို ပြောဆိုရာတွင် သူတစ်ပါးကိုချိုးနှိမ်ရှုတ်ချပြီး မိမိကိုယ်ကို အမွှမ်းတင်ခြင်းသည် များစွာဖြစ်လေ့ရှိသောသဘောဖြစ်သည်။”')
,(11061,3,1,'ကမ္ဘာမြေကြီး။ ကမ္ဘာလောကနှင့် ပတ်သက်သောအရာ။ လောကီရေးရာ။ လောကီလူသား။','“အိုတ်ဇၟာပ်ဘူဝတ်၊ သတ်ပုထုဇန်။ ယဝ်ရဒက်မိတ်၊ လအိတ်ဗိုန်က္ညန်။” (လိက်သောဝါနနဟောၚ်) = “ပုထုဇဉ်သတ္တဝါဖြစ်သော အလုံးစုံသောလောကီလူသားတိုင်းသည် အကယ်၍မိတ်ဖွဲ့မည်ဆိုလျှင် အလွန်ခိုင်မြဲနိုင်၏။”')
,(11062,3,10,'(န) ကွဲပြားခြင်း။ ပျက်စီးခြင်း။ အပြား။ အထူးအပြား။',NULL)
,(11063,3,1,'ဘေး။','ဒးဘဲ = ဘေးတွေ့သည်။ ရိုက်ပုတ်ခြင်းခံရသည်။')
,(11064,3,1,'သေဘေး။','“မၞိဟ်ဂမၠိုၚ်ဂှ် ဗၠးဘဲဂစိုတ်တုဲ နတသိုက်ဟေၚ်သ္ဍးအာရ။” (ဇ—၄ဝ၅။အစွောံ။) = “လူများသည် သေဘေးမှလွတ်၍ ချမ်းသာသဖြင့် ဖဲခွါသွားကြကုန်၏။”')
,(11064,3,1,'သေဘေး။','“ဍေံတံဖေက်ဘဲဂစိုတ်တုဲ ဍေံတံဒြေပ်အာအိုတ်တုဲရ။” (ဇ—၅ဝ၁။ အစွောံ။) = “သူတို့သည် သေဘေးကိုကြောက်၍ ထွက်ပြေးသွားကြကုန်ပြီ။”')
,(11065,3,1,'ဘေးဒဏ်။ ရိုက်နှက်ပြစ်ဒဏ်ပေးခြင်း။ အပြစ်ဒဏ်။','“မူဟိုတ်ဒှ်မ္ဒးဘဲလ္ၚဂလိုၚ်ဝွံရော။” (အကြီုရာဇာဓိရာဇ်) = “အဘယ်ကြောင့် ဤမျှပြင်းထန်စွာ ရိုက်နှက်ပြစ်ဒဏ်ပေးခြင်း ခံရပါသနည်း။”')
,(11065,3,1,'ဘေးဒဏ်။ ရိုက်နှက်ပြစ်ဒဏ်ပေးခြင်း။ အပြစ်ဒဏ်။','“တန်ဂွံဆေဝ်တာဒနာဍေံဟာ ဍေံဂးတုဲ ဘဲလ္ၚဂလိုၚ်ဝွံ မပပရိုက်ကဵုအဲဍိက်။” (အကြီုရာဇာဓိရာဇ်) = “သူ့ကိုတားမြစ်ရကောင်းလားဟုသူဆိုကာ ကျွန်တော်မျိုးအား ဤမျှရက်စက်စွာ ရိုက်နှက်ပြစ်ဒဏ်ပေး၏။”')
,(11065,3,1,'ဘေးဒဏ်။ ရိုက်နှက်ပြစ်ဒဏ်ပေးခြင်း။ အပြစ်ဒဏ်။','“တုပ်ညံၚ်ဂြာဲပၠန်၊ ညန်တဲလၟ။ ဒးဒုၚ်ဒဒိုက်၊ ပရိုက်ဘဲလ္ၚ။” (လိက်ပရေၚ်ခန္ဓ) = “မုဆိုးလက်သို့ရောက်သောသမင်ကဲ့သို့ ဒုက္ခဘေးဒဏ်ခံရ၏။”')
,(11065,3,1,'ဘေးဒဏ်။ ရိုက်နှက်ပြစ်ဒဏ်ပေးခြင်း။ အပြစ်ဒဏ်။','“ဗှ်သၟိၚ်မပ၊ ဘဲလ္ၚဒးဒုၚ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်) = “မင်းကပြုသော ရိုက်နှက်အပြစ်ပေးခြင်းဒဏ်ကို ခံရသည်ကိုတွေး၍။”')
,(11065,3,1,'ဘေးဒဏ်။ ရိုက်နှက်ပြစ်ဒဏ်ပေးခြင်း။ အပြစ်ဒဏ်။','“ဟွံဒှ်ညံၚ်ဟီု၊ ပ္ကီုဒဏ်ဘဲလ္ၚ။ တက်စးစဲတ္ၚဲ၊ ပျဲဒဵုချိုတ်ရ။” (လိက်ဇိဝှစက္က) = “ပြောသလိုမဖြစ်၍ အပြစ်ဒဏ်ခတ်လော့။ ကျောက်ကုန်းကိုရိုက်နှက်၍ နေပူလှန်းကာ သေသည်အထိ ညှဉ်းဆဲလော့။”')
,(11066,3,11,'(န) ဘောဇဉ်။ (ထမင်း၊ မုန့်မှုန့်၊ မုယောမှုန့်၊ ငါး၊ အသားဟူသော) စားဖွယ်။','“ဘောဇိုန်မၞုံကဵုရှ် ညံၚ်သၟိၚ်မစဂှ် စဳရေၚ်ကဵုရ။” (ဇ—၄ဝ၉။ အစွောံ။) = “မင်းအားသာထိုက်သော အထူးထူးသော အရသာရှိသောဘောဇဉ်ကို ပေး၏။” (ညောင်ကန်)')
,(11067,3,10,'(န) ပစ္စည်းဥစ္စာ။ စည်းစိမ်ချမ်းသာ။','“အတိက်တမၠာ၊ ပ္တုဲလဝ်ဒါန။ — စသိုၚ်ဘောဂ၊ သီုတေဇတုန်။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “ရှေးအတိတ်က ဒါနပြုထားသဖြင့် ဘုန်းတေဇာနှင့်တကွ စည်းစိမ်ချမ်းသာကို စံစားရ၏။”')
,(11068,3,10,'(န) ဘောဂဗေဒ။ (ကုန်ထုတ်အရင်းအနှီး၊ ကုန်ထုတ်လုပ်မှု၊ ကုန်လုပ်ဆက်ဆံရေးစသည်တို့ကို လေ့လာသောပညာရပ်။)',NULL)
,(11069,3,5,'မရေမတွက်နိုင် အလွန်များပြားစွာ။',NULL)
,(11070,3,11,'(န) ဘဝ။','“ယွံဂၞကျာ်၊ — ပ္ဍဲဘဴအတိက်တေံဂှ် ဟိုတ်ဂၞကျာ်ဂွံကလၚ်ပၚ်မှိၚ်ဓဝ်မပြဲတုဲဂှ် ပ္ဍဲဘဴလၟုဟ်ဂှ် ၜိုန်ကျာ်တြဲဟွံမွဲကီုရ၊ ဂၞကျာ်ညးမပြဲ မဂွံမိၚ်တဝှ်ဓဝ်မပြဲကီုရောၚ်ဟွံသေၚ်ဟာ။” (ဇ—၅ဝ၂။ အစွောံ။) = “အရှင်မိဖုရား၊ အတိတ်ဘဝက မြတ်သောတရားကို နာကြားခဲ့ဖူးသောကြောင့် ယခုဘဝ­ မြတ်စွာဘုရားမပွင့်သော်လည်း မြတ်သောအရှင်မိဖုရားသည် မြတ်သောတရားကို နာကြားရသည်မဟုတ်လော။”')
,(11070,3,11,'(န) ဘဝ။','“ဒေဝတဴဇြဲ၊ ပ္ဍဲဘဴတမၠာ။ ဒှ်မိညးၜါ၊ အတိက်ကာလ။” (လိက်တပူတဗဝ်) = “ညောင်စောင့်နတ်သည် ရှေးဘဝအတိတ်ကာလက ထိုသူနှစ်ဦးတို့၏မိခင်ဖြစ်ခဲ့ဖူး၏။”')
,(11071,3,11,'(န) ဘုန်းကံ။ (ပါဠိ—ဘဂ္ဂ)','‘ညးမနွံဘက်၊ တြုံပြဲအဂ္ဂ။’ (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = ‘ဘုန်းကံရှိသော ကြီးမြတ်သောယောကျာ်း။’')
,(11071,3,11,'(န) ဘုန်းကံ။ (ပါဠိ—ဘဂ္ဂ)','‘ဗြဴဒတိုန်ဘက်။’ (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = ‘ဘုန်းကံရှင်မိန်းမ (ဝါ) ဘုန်းကံတက်သောမိန်းမ။’')
,(11071,3,11,'(န) ဘုန်းကံ။ (ပါဠိ—ဘဂ္ဂ)','(ကြိ) မစသည်။ စောၚ်မသည်။ ထောက်ကူသည်။ (?)')
,(11071,3,11,'(န) ဘုန်းကံ။ (ပါဠိ—ဘဂ္ဂ)','“ကုသဵုဘက်သွက်ပိုဲရောၚ်။ ဟွံဒးအာသ္ၚောဲရ။” (ဇ—၂၃၂။ အစွောံ။) = “ငါတို့အဖို့ ကုသိုလ်က ထောက်ကူစောၚ်မ၏။ ဝေးဝေးသွားစရာမလိုတော့ပါ။”')
,(11072,3,1,'လက်မှန်း။ ပစ်ခတ်ရန်အတွက် လက်ဖြင့်ချိန်ရွယ်ချက်။','“ဟာဲတ္ၜိုၚ်၊ လတုန်ဝွံဘက်ကရီုတဲဟွံသ္ဍာံ ဆောတ်ယောၚ်တုဲ (ဗှ်ေ) ဗၠးအာရ” လၟဂး။ (ဇ—၂၁။ အစွောံ။) = “ဟယ်ဆတ်၊ ဤအကြိမ်­ ငါ့လက်မှန်းမဖြောင့်ဘဲ ချွတ်ယွင်း၍ သၚ်လွတ်သွား၏” ဟုမုဆိုးဆို၏။')
,(11073,3,1,'တစ်ဝက်။','ဘာ်န = တင်းတစ်ဝက်။')
,(11073,3,1,'တစ်ဝက်။','ဘာ်နာဍဳ = နာရီဝက်။')
,(11073,3,1,'တစ်ဝက်။','ဘာ်တ္ၚဲ = နေ့တစ်ဝက်။')
,(11073,3,1,'တစ်ဝက်။','“ဍာ်တုန်ဘာ်သြၚ်။” = “ကမ်းတစ်ဝက်ရေတက်သည်။”')
,(11074,3,5,'ဝမ်းတစ်ဝက်မျှသာ။ ဝမ်းမဝဘဲ။ မဝရေစာ။','“ဒးကၠောန်ဍောၚ်ၜိုတ်တဴ ဗွဲမလောန်ဂှ်လေဝ် ဂွံစတဴဆဘာ်ဂၞဴကီု။” = “အလွန်ပင်ပန်းစွာ လုပ်ရသော်လည်း မဝရေစာမျှသာ စားရသည်။”')
,(11075,3,1,'လမ်းတစ်ဝက်။ ခရီးတစ်ဝက်။','“သၟိၚ်ပေါရိသာဒဂှ် ပလံၚ်ဗက်တိတ်အာဘာ်တရဴတုဲကလေၚ်စဴကၠုၚ်ရ။” (ဇ—၅၃၇။ အစွောံ။) = “ပေါရိသာဒမင်းသည် ခရီးတစ်ဝက် လိုက်ပါပို့ဆောင်ပြီး ပြန်လာ၏။”')
,(11075,3,1,'လမ်းတစ်ဝက်။ ခရီးတစ်ဝက်။','“စိုပ်ဘာ်တရဴ ဇိုၚ်ချေံတၠညးကဝ်အာ။” (ဇ—မဟောဟ်သဓ။ အစွောံ) = “လမ်းတစ်ဝက်အရောက်တွင် မင်းကြီး၏မြင်းခြေကျိုးသွား၏။”')
,(11075,3,1,'လမ်းတစ်ဝက်။ ခရီးတစ်ဝက်။','‘ဒေါဝ်တရဴ’ (န) လည်းရှု။')
,(11076,3,4,'လာရန်ပန်ကြားသည်။ ဖိတ်သည်။ ဖိတ်ကြားသည်။',NULL)
,(11077,3,10,'(န) ရဟန်း။ ရဟန်းယောကျာ်း။',NULL)
,(11078,3,10,'(န) ရဟန်းမိန်းမ။',NULL)
,(11079,3,11,'(န) စည်းစိမ်ဥစ္စာ။','“ယွံမၞးတံ၊ ပိုဲတုန်လေဝ် နွံတဴပိုန်ဟာန်ဘိုက်ဘက် ဗွဲမဂၠိုၚ်ရ။ ဂှ်လေဝ် ပိုဲဟွံဂွံပ္တုဲလဝ်ဒါန်။” (ဇ—၃၁၄။ အစွောံ။) = “အချင်းတို့၊ ငါတို့သည် များစွာသောစည်းစိမ်ဥစ္စာရှိကုန်၏။ သို့သော်လည်း ငါတို့ဒါနမပြုခဲ့ရ။”')
,(11079,3,11,'(န) စည်းစိမ်ဥစ္စာ။','“ယွံသၟိၚ်မ၊ ပ္ဍဲဍုၚ်သွဝ်တေံဂှ်ထာန်မဂပ်ဂဝ်လှိၚ်စိုတ်ရောၚ်။ — ပိုန်ဟာန်ဘိုက်ဘက်မအံက် မဒှ်ဘိုက်ဘက်မၞိဟ်ဂှ် မူသ္ပကဵုဍေံရော” ကောန်သၟိၚ်ဂး။ (ဇ—၅ဝ၅။ အစွောံ။) = “ခမည်းတော်မင်းကြီး၊ ထိုနတ်ပြည်­ မွေ့လျော်ဖွယ်ကောင်း၏။ လူ့စည်းစိမ်မျှသာဖြစ်သော ခမည်းတော်၏စည်းစိမ်သည် ဘာပြုရအံ့နည်း”ဟုမင်းသားဆို၏။')
,(11079,3,11,'(န) စည်းစိမ်ဥစ္စာ။','“ဗောဓိသတ်ပိုဲ က္တဵုဒှ်ပ္ဍဲဂကူညးမၞုံကဵုဘိုက်ဘက်မွဲတုဲ—။” (ဇ—၉၁။ အစွောံ။) = “ဘုရားလောင်းသည် တဦးသော များစွာသောစည်းစိမ်ရှိသောအမျိုး­ဖြစ်၏။” (ညောင်ကန်)')
,(11080,3,12,'(န) ဆေးခြောက်ပၚ်။ ဆေးခြောက်။ ဘင်း။ (မူးယစ်ဆေး) (သ—ဘၚ်္ဂ)',NULL)
,(11081,3,11,'(န) ပျက်ဆဲအခိုက်အတန့်။ ဘၚ်။ (ပါဠိ—ဘၚ်္ဂ)',NULL)
,(11082,3,4,'တွေဝေသည်။ ကြောက်လန့်၍ဖြစ်စေ၊ အံ့အားသင့်၍ဖြစ်စေ၊ ရုတ်တရက်ဘာလုပ်ရမှန်းမသိဖြစ်သည်။',NULL)
,(11083,3,4,'တွေဝေသည်။ မိန်းမောသည်။','“ဒှ်တဴပူဆာ၊ လ္ၚာပ်လ္ၚာဘၚ်တ္ၜိၚ်။” (လိက်ပဒုမဝတဳ) = “ပူဆွေးပူပန်တွေဝေသည်။”')
,(11083,3,4,'တွေဝေသည်။ မိန်းမောသည်။','“မြုထၜိုၚ်၊ ကမာၚ်ဗိုၚ်ရေၚ်။ တရၚ်တုန်ဟေၚ်၊ လမေၚ်နာမ။ ဒစိတ်ပနော်၊ ဇၞော်သိဒ္ဓိက။ ညာတ်ဒးဘၚ်တ္ၜိၚ်၊ လဟိၚ်စိတ္တ။” (လိက်ကာလထေ) = “တံတိုင်း၊ ကျုံး၊ မြို့ရိုးတို့သည် ဝန်းရံစီတန်းနေကုန်၏၊ တံခါးကိုးပေါက်သည်လည်း အောင်ခြင်းသိဒ္ဓိကြီးမား၏၊ မြင်ရသည်ရှိသော် မိန်းမော၍ စိတ်မှာသာယာကြည်နူး၏။”')
,(11083,3,4,'တွေဝေသည်။ မိန်းမောသည်။','“ပ္ဍဲစိုတ်ဘၚ်ၜိၚ်၊ ဗှ်ဂွိၚ်တိုန်ဟေၚ်။ ဒှ်တိုန်ပါတ်သ္ဗ၊ စိတ္တပ္ဍီုသေၚ်။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “စိတ်တွေဝေပူပန်လာကာ စိတ်ပူဆွေးညှိုးနွမ်းလာ၏။”')
,(11083,3,4,'တွေဝေသည်။ မိန်းမောသည်။','“သၟိၚ်ဖေက်ဓည၊ ကမၠဘၚ်က္ၜိၚ်။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်။) = “မင်းသည် ကြောက်ရွံ့ထိတ်လန့် စိတ်နောက်တွေဝေ၏။”')
,(11084,3,4,'ယစ်မူးသည်။ မိန်းမူးသည်။ အာရုံမကြည်မလၚ်ဖြစ်သည်။','“စိုပ်သ္ၚိသ္ၚိတူ၊ ဗဟူဒုက္ခာ။ ဒဒိုက်စိုပ်သြၚ်၊ ဝိဝိၚ်ဘၚ်ယာ။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) = “အိမ်ရောက်သော်အိမ်မီးလောင်၍ ဒုက္ခများ၏၊ ကမ်းသို့ရောက်သော် ဒုက္ခကြောင့် တွေဝေမိန်းမူး အာရုံမကြည်မလၚ်ဖြစ်၏။”')
,(11085,3,5,'အနည်းငယ်ယစ်မူးလျက်။ ထွေလျက်။','“သူရာဇးရ၊ ယက္ခဗြဴရတ်။ —ဘၚ်ဘၚ်ယာယာ၊ တွာ်အာမိလောတ်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “သုရာယစ်ခြင်းပြေသော ဘီလူးမသည် အနည်းငယ်ထွေနေသေးလျက် လျှောက်သွားရာ လဲကျ၏။”')
,(11086,3,4,'တွေဝေသည်။ မဆုံးဖြတ်နိုင် မဝေခွဲနိုင်ဖြစ်သည်။','“မောဟဃလီု၊ ဓီုဓုဲဟွံခြာ။ ဝိဝိၚ်ဝိုတ်ဝုဲ၊ ဘၚ်ဘုဲဒှ်အာ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “မောဟလွှမ်းမိုး၍ ထုံထိုင်းကာ တွေဝေမေ့လျော့ပြီး မဝေခွဲနိုင်ဖြစ်၏။”')
,(11087,3,4,'မူးမိုက်တွေဝေသည်။ ကြောက်လန့်၍ဖြစ်စေ၊ အံ့အားသင့်၍ဖြစ်စေ ရုတ်တရက်မလှုပ်မရှားနိုင်ဖြစ်သည်။','“(ဂၞကျာ်မဒ္ဒဳ) ဆဵုသၟိၚ်သတ်ပိ (ကၠ၊ ဗြန်၊ ဇာဒိသိုၚ်တုဲ) — ဂြိုဟ်ညံၚ်မဖာဲအာကီု ဂၞကျာ်ဘၚ်သၠၚ်ဝိဝိၚ် ဒွိၚ်ပ္ဍဲကောန်ၜါကဵုမှာရသိ—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) =“မဒ္ဒီမိဖုရားသည် သားတို့၏မင်းဖြစ်သော သုံးခုကုန်သော ကျား၊ သစ်၊ ခြင်္သေ့တို့ကို ဆုံတွေ့သည်ရှိသော် နှလုံးကွဲအံ့သကဲ့သို့ ကြောက်လန့်မူးမိုက်တွေဝေကာ ကလေးနှစ်ယောက်နှင့် ဝေဿန္တရာရသေ့ကြီးအတွက် စိတ်ပူ၏။”')
,(11087,3,4,'မူးမိုက်တွေဝေသည်။ ကြောက်လန့်၍ဖြစ်စေ၊ အံ့အားသင့်၍ဖြစ်စေ ရုတ်တရက်မလှုပ်မရှားနိုင်ဖြစ်သည်။','“(ဂၞကျာ်မဒ္ဒဳလောတ်သ္ၚဳဒၟံၚ်ဂှ် ဂၞကျာ်ပကာဂစိုတ်ရဟာဂးတုဲ သၟိၚ်ဝေသန္တဝ်ဂွိၚ်တဴ) ဇၞော်ကဵုဒြဟတ် ဘၚ်သၠၚ်ဝိဝိၚ်ဘိၚ်တလိၚ်အာတုဲ တၞဟ်နစၟတ်ဓဝ်ခမဳ ဟွံသၟဟ်ရထ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “မဒ္ဒီမိဖုရားမေ့မြောလဲနေစဉ် မိဖုရားသေလေပြီလောဟု ဝေဿန္တရာမင်းသည် စိုးရိမ်ခြင်းကြီးစွာဖြစ်၍ မူးမိုက်တွေဝေလျက် ကြက်သေသေ၍ ရဟန်းတရားကို မှတ်အံ့သောငှာမတတ်နိုင်။”')
,(11088,3,1,'ဘိန်း။ (မူးယစ်ဆေး)','စဘိၚ် = ဘိန်းစားသည်။')
,(11088,3,1,'ဘိန်း။ (မူးယစ်ဆေး)','ဇြောတ်ဘိၚ် = ဘိန်းရှူသည်။')
,(11088,3,1,'ဘိန်း။ (မူးယစ်ဆေး)','“ဘိၚ်အရက်ကီု၊ ကဵုကံက်သီုဖျာ။” (လိက်ဇိဝှစက္က) = “ဘိန်း၊ အရက်တို့နှင့်တကွ တစ်ဈေးလုံးကို အကောက်ကောက်စေ၏။”')
,(11089,3,4,'တွေဝေသည်။ ကြက်သေသေသည်။ ထိတ်လန့်အံ့အားသင့်၍ ကြောင်တက်တက်ဖြစ်သည်။','“(ဂၞကျာ်မဒ္ဒဳလောတ်သ္ၚဳဒၟံၚ်ဂှ် ဂၞကျာ်ပကာဂစိုတ်ရဟာဂးတုဲ သၟိၚ်ဝေသန္တဝ်ဂွိၚ်တဴ) ဇၞော်ကဵုဒြဟတ် ဘၚ်သၠၚ်ဝိဝိၚ်ဘိၚ်တလိၚ်အာတုဲ တၞဟ်နစၟတ်ဓဝ်ခမဳ ဟွံသၟဟ်ရထ—။” (ဇ—ဝေသန္တဝ်။အစွောံ။) = “မဒ္ဒီမိဖုရားမေ့မြောလဲနေစဉ် မိဖုရားသေလေပြီလောဟု ဝေဿန္တရာမင်းသည် စိုးရိမ်ခြင်းကြီးစွာဖြစ်၍ မူးမိုက်တွေဝေလျက် ကြက်သေသေ၍ ရဟန်းတရားကို မှတ်အံ့သောငှာမတတ်နိုင်။”')
,(11089,3,4,'တွေဝေသည်။ ကြက်သေသေသည်။ ထိတ်လန့်အံ့အားသင့်၍ ကြောင်တက်တက်ဖြစ်သည်။','“ဒှ်တဴဝိဝိၚ်၊ ဘိၚ်တလိၚ်အာ။ ဟွံတီဒိုဟ်ကၠၚ်၊ ဘိၚ်ဘၚ်မှာရာ။” (လိက်မိဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “တွေဝေ၍ ကြက်သေသေသကဲ့သို့ဖြစ်ကာ အရပ်မျက်နှာကိုမသိဘဲ ကြောင်တက်တက်ဖြင့် အလွဲလွဲအမှားမှားဖြစ်သွား၏။”')
,(11090,3,4,'မိန်းမောတွေဝေသည်။ ကြက်သေသေမျှ တွေဝေမူးမိုက်သည်။','“ဆုကြက်လကံဂှ်ကြံၚ်လောန် ချိုန်မၜံက်ဂှ်ဟေၚ် (ဂစေံဂန္ဒကဂှ်) စမဴဂှ်ပါ်အာတုဲ ခဍောၚ်မတ်ညံၚ်မဗၠတ်တိတ်အာက္ဍိုပ်ညံၚ်ဒကးအာကီုဒှ်တုဲ ဘိၚ်ဘၚ်ဒတုံစှ်ေအာဒဵုတိ—။” (ဇ—၂၁ဝ။ အစွောံ။) = “ရှားပင်သည်အလွန်မာ၏။ ဂန္ဒကငှက်သည် ရှားပင်ကို နှုတ်သီးဖြင့်ပေါက်သည်ရှိသော် နှုတ်သီးသည်ပြတ်၏။မျက်လုံးတို့သည် ပြုတ်ထွက်ဘိသကဲ့သို့ ဦးခေါင်းသည် ကွဲဘိသကဲ့သို့ဖြစ်၍ တွေဝေမူးမိုက်လျက်မြေသို့ကျ၏။”')
,(11090,3,4,'မိန်းမောတွေဝေသည်။ ကြက်သေသေမျှ တွေဝေမူးမိုက်သည်။','“စိၚ်ဇၟူတၠအစောံ ဂွံညာတ်ကေတ်ကမၠံၚ်ဗြဴဗက်ဟေၚ် ကြအ်ဗ္ၜူဘိၚ်ဘၚ်တဴ ဗက်စဴကြဴကြဴကမၠံၚ်ဗြဴ—။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “အားအစွမ်းကြီးသောဆင်ပြောင်သည်ဆင်ပျိုမကိုတွေ့သည်နှင့် ရူးမူးတွေဝေမိန်းမောကာ ဆင်မနောက်သို့ တကောက်ကောက်လိုက်သွား၏။”')
,(11090,3,4,'မိန်းမောတွေဝေသည်။ ကြက်သေသေမျှ တွေဝေမူးမိုက်သည်။','“လ္ပဟိုတ်မာဲ၊ ဂၠာဲဓဝ်ဍာံပြ။ လ္ပဝိဝိၚ်၊ ဘိၚ်ဘၚ်မောဟ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “တရားအမှန်ကိုရှာ မမေ့မလျော့နှင့်။ မောဟဖြင့်မတွေဝေ မမိန်းမူးလေနှင့်။”')
,(11091,3,4,'မူးဝေသည်။','က္ဍိုပ်ဘိုၚ် = ခေါင်းမူးသည်။')
,(11091,3,4,'မူးဝေသည်။','မှုဲဘိုၚ် = ခေါင်းမကြည်မသာဖြစ်သည်။')
,(11092,3,4,'ဝိုင်းကူသည်။','‘ဘိုၚ်ကၠောန်အိုတ်ညိ။’ = ‘ဝိုင်းကူလုပ်ကြပါ။’')
,(11092,3,4,'ဝိုင်းကူသည်။','‘ဗိုၚ်’ (ကြိ—၂) ၊နှင့်အတူတူ။')
,(11093,3,4,'တွေဝေသည်။',NULL)
,(11094,3,4,'မူးဝေသည်။ ခေါင်းနောက်သည်။ (စားပြီး၍) အဆီယစ်သည်။ ထိုင်းမှိုင်းသည်။','“အဲမံၚ်စဟွံမိပ်က္ဍၚ် ဘိုၚ်ဘုဲဒၟံၚ်ညိရ။” = “ငါသိပ်နေမကောင်း အနည်းငယ်မူးဝေနေသည်။”')
,(11094,3,4,'မူးဝေသည်။ ခေါင်းနောက်သည်။ (စားပြီး၍) အဆီယစ်သည်။ ထိုင်းမှိုင်းသည်။','“စဟာပ်တုဲအဴ၊ ဒှ်တဴဇြဟတ်။ ဒှ်တိုန်ဘိုၚ်ဘုဲ၊ ဒကုဲပ္ဍဲမတ်။” (လိက်မိဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) =“အစာစားပြီးနောက် ခွန်အားဖြစ်လာ၍ အဆီယစ်ထိုင်းမှိုင်းလာကာ ငိုက်မျဉ်းလာ၏။”')
,(11095,3,4,'မူးဝေသည်။ မကြည်မသာဖြစ်သည်။','“ပူဂဵုမွဲဂှ်၊ လနောဟ်ဘိုၚ်မှုဲ။ သ္တိက်လနောဟ်က္တဵု၊ ဒဵုသၠုၚ်သၠၚ်တုဲ။” (လိက်လၞုဟ်ပန်) = “တစ်ယောက်သောသူသည် ပျင်းရိကာ မကြည်မသာဖြစ်၏၊ အိပ်ပြီး နေမြင့်သည့်တိုၚ်သောၚ် ထဖို့ပျင်း၏။”')
,(11096,3,12,'(န) တော်သလင်းလ။',NULL)
,(11097,3,12,'(န) ဘဒ္ဒကမ္ဘာ။',NULL)
,(11098,3,10,'(န) ပြာ။ ဖွဲပြာ။','“ယာံစိၚ်ဂမၠိုၚ်ဂွံကျာမၞိဟ် ဆဵုဒးသတြုတုဲ လၞိန်ဖလှေက်ကၠေံဒှ်အာဘသၟရောၚ်။” (ဇ—၅၁၄။ အစွောံ။) = “ထိုဆင်များသည် လူနံ့ရ၍ ရန်သူကိုမြင်သည်ရှိသော် ဖွဲပြာဖြစ်သွားအောင် နင်းခြေပစ်ကြလိမ့်မည်။”')
,(11098,3,10,'(န) ပြာ။ ဖွဲပြာ။','“သၟိၚ်ဗဳသြဴကုမ္ဘန်ထေဲတုဲ သ္ၚဳဒးမ္ဂး ဒှ်အာဘသၟရ။” (ဇ—၂၈၁။ အစွောံ။) = “ဝေဿဝဏ်နတ်မင်းသည် အမျက်ထွက်၍ ကြည့်သည်ရှိသော် ဖွဲပြာဖြစ်သွားလိမ့်မည်။”')
,(11098,3,10,'(န) ပြာ။ ဖွဲပြာ။','“နကျာ်မုဟ်တသိုဟ်ပ္တိတ်တုဲ သီုဍုၚ်ဂှ် ကဵုဒှ်အာဘသ္မဟာအဴ”နာ်ဂမၠိုၚ်သၟာန်သၟိၚ်နာ်။ (ဇ—ဘူရိဒတ်။ အစွောံ။) = “နှာခေါင်းလေဖြင့်မှုတ်ထုတ်၍ မြို့အလုံးကိုဖွဲပြာဖြစ်သွားအောင် ပြုရအံ့လော” ဟုနဂါးများက နဂါးမင်းကိုမေး၏။')
,(11098,3,10,'(န) ပြာ။ ဖွဲပြာ။','‘ဗတ်သၟ’ နှင့်အတူတူ။')
,(11099,3,4,'(ထွက်ခွါသွားအောင်) မောင်းသည်။ နှင်သည်။','ဘာတ်ဖျေံနူသ္ၚိ = အိမ်မှနှင်ချသည်။')
,(11099,3,4,'(ထွက်ခွါသွားအောင်) မောင်းသည်။ နှင်သည်။','“ဗောဓိသတ် (တေမဳ) ဘာတ်ဖျဴသာရထဳရ။” (ဇ—တေမဳ။ အစွောံ။) = “ဘုရားလောင်း (တေမိ) သည် ရထားထိန်းအား ပြန်ရန်နှင်လိုက်၏။”')
,(11099,3,4,'(ထွက်ခွါသွားအောင်) မောင်းသည်။ နှင်သည်။','“ဒေဝတဴဆုကသမ်ဝွံ ဘာတ်ပ္တိတ်အဲရ။ လဝ်ကဵုပကဵုအဲကၠာရ” ကၟီဂး။ (ဇ—၄၇၅။ အစွောံ။) = “ဤကြို့ပၚ်စောင့်နတ်သည် ငါ့အားမောင်း ထုတ်၏။ ငါ့အား လုပ်ထားနှင့်ဦးပေါ့” ဟုဝံဆို၏။')
,(11100,3,1,'၁။ ဖုတ်သရဲ။','“ကလော်ဘုတ်ပြိုတ်ခါခဏဳတံဂှ် ဍေံစ္ဍးအာအိုတ်ရ။” (ဇ—၄၉၇။ အစွောံ။) = “ဘီလူး၊ ဖုတ်သရဲ၊ ပြိတ္တာအစရှိသော မကောင်းဆိုးဝါးတို့သည် ပြေးခွာသွားကုန်၏။”')
,(11100,3,1,'၁။ ဖုတ်သရဲ။','“ကလော်အပိၚ်သာတ် အကြာဟန်ဗန်တံဂှ်ကီု၊ ဘုတ်ပြိုတ်တံဂှ်ကီု။” (ဇ—၅၁ဝ။ အစွောံ။) = “အမှိုက်ပုံကြားမှ မြေဘုတ်ဘီလူးတို့သည်၄င်း၊ ဖုတ်ပြိတ္တာတို့သည်၄င်း။”')
,(11100,3,1,'၁။ ဖုတ်သရဲ။','၂။ ဘုရားဝတ်ကျောင်း။')
,(11100,3,1,'၁။ ဖုတ်သရဲ။','‘စေတဳဘုတ်ဘာကၟာ။’ = ‘စေတီဘုရားကျောင်းကန်။’')
,(11100,3,1,'၁။ ဖုတ်သရဲ။','“ညးကၠောန်ထၜုတ်၊သိုၚ်ဘုတ်သိုၚ်ဘာ။” (လိက်ကာလထေ) = “သူတကာတို့သည် ဘုရားဝတ်ကျောင်းဆောက်ကြ ကျောင်းဆောက်ကြကုန်၏။”')
,(11101,3,1,'ပထဝီ၊ အာပေါ၊ တေဇော၊ ဝါယောဟူသော ဓါတ်ကြီးလေးပါး။ မဟာဘုတ်။','“ပဟိုတ်ကဵုဘုတ်ပန်ဂှ် မတွံဂးပထဝဳ၊ အာပေါ၊ တေဇော၊ ဝါယောတုဲ ရုပ်မက္တဵုဒှ်ရောၚ်။” (ဇ—၅၂၈။အစွောံ။) = “ပထဝီ၊ အာပေါ၊ တေဇော၊ ဝါယောဟူသော မဟာဘုတ်လေးပါးကို အကြောင်း ပြု၍ ရုပ်ဖြစ်ပေါ်လာ၏။”')
,(11102,3,11,'အစားပေးလျော်ခြင်း။ (ပါဠိ—ဘဏ္ဍဒေယျ)',NULL)
,(11103,3,10,'(န) ပစ္စည်းဥစ္စာ။ ဘဏ္ဍာ။',NULL)
,(11104,3,10,'(န) အရှင်ဘုရား။','“ညးမသွတ်အဵု၊ မအန်ကဵုဝှ်။ ဘန္တေကဵုကော်၊ ညးဇၞော်ကြဳဇှ်။ ညးဇမၞော်ဂှ်၊ ဗဒှ်အဆတ်။ အာဝုသောဂး၊ ကဵုညးမသၟတ်။” (လိက်ပထမဗောဓိ။ မၚ်ဍိက်လ။) =“ငယ်ရွယ်သော ဝါစဉ်ငယ်သောရဟန်းက ကြီးသူကို ဘန္တေ (အရှင်ဘုရား) ဟုခေါ်စေ၊ ကြီးသောရဟန်းက ငယ်သူကို အာဝုသော (ငါ့ရှင်) ဟုခေါ်စေ။”')
,(11105,3,4,'(လုပ်စရာရှိသည်ကို မလုပ်ဘဲ)ငေးငိုင်တွေဝေသည်။ လေးလံထိုင်းမှိုင်းသည်။ မှုန်ကုပ်ကုပ်နေသည်။','“သ္ဇက်ကၠောန်နွံဂှ် ကၠောန်ရ၊ လ္ပဘိန်ဒၟံၚ်။” = “လုပ်စရာရှိတာလုပ်၊ငေးငိုင်တွေဝေမနေနှင့်။”')
,(11106,3,1,'ဘိန်း။','‘ဘိၚ်’ ဟုလည်းရေးသည်။')
,(11107,3,10,'(န) ပျားပိတုန်း။','“ဘိမ္မရာ၊ ၚ်ထိုၚ်သာဲတံဂှ်။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ပိတုန်းပျားတို့သည်—။”')
,(11107,3,10,'(န) ပျားပိတုန်း။','“သာဲဘိမ္မရာ၊ မှောဝ်ဇာလဳၜန်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) =“ပျားပိတုန်းတို့သည် ပျော်ရွှင်ရောယှက်နေကုန်၏။”')
,(11108,3,11,'(န) ၁။ ဘုံ။ သတ္တဝါတို့ ဖြစ်တည်ရာဋ္ဌာန။ (ပါဠိ—ဘူမိ)','ပိစှ်ောမွဲဘုံ =သုံးဆယ့်တစ်ဘုံ။')
,(11108,3,11,'(န) ၁။ ဘုံ။ သတ္တဝါတို့ ဖြစ်တည်ရာဋ္ဌာန။ (ပါဠိ—ဘူမိ)','၂။ ပြာသာဒ်အဆင့်အထပ်။ ပြာသာဒ်ဘုံ။')
,(11108,3,11,'(န) ၁။ ဘုံ။ သတ္တဝါတို့ ဖြစ်တည်ရာဋ္ဌာန။ (ပါဠိ—ဘူမိ)','ပြာသာဒ်မၞုံထပှ်ဘုံ = ဘုံခုနစ်ဆင့်ရှိသောပြာသာဒ်။')
,(11109,3,1,'ဘုမ္မစိုးနတ်။ မြေ­တည်မှီသောနတ်။','“အကာသဇဵုဂျ၊ ပၠဘုမ္မဇဵုကၠာ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “အာကာသစိုးနတ်ကို၄င်း ဘုမ္မစိုးနတ်ကို၄င်း။”')
,(11110,3,1,'စေတီဖောင်းရစ်။','‘ပွူကၠန်’ (န) နှင့်အတူတူ။')
,(11111,3,12,'(န) ပရုတ်အရိုင်း။ ဖုံးမသိန်။ (ပရုတ်ဓါတ်ပါသော ဆေးဖက်ဝင်အပင်)','“မြမောဝ်ပန်သာ် မပ္တံစလန်၊ အဂၠဴ၊ ဂဒဵု၊ ဘုံမသိုန်။” (ဇ—၄၉၇။ အစွောံ။) = “စန္ဒကူး၊အကျော်၊ ကတိုး၊ ဖုံးမသိန်အစရှိသော နံ့သာမျိုးလေးပါး။”')
,(11111,3,12,'(န) ပရုတ်အရိုင်း။ ဖုံးမသိန်။ (ပရုတ်ဓါတ်ပါသော ဆေးဖက်ဝင်အပင်)','“ဘုမ္မသိုန်သၟတ်၊ သီုပရုတ်မောဝ်လောန်။” (လိက်ဇိဝှစက္က) = “အလွန်မွှေးသော ဖုံးမသိန်နှင့်ပရုတ်။”')
,(11112,3,13,'(ဝိ) အတွက်၊ အဖို့။',NULL)
;